import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress, formatAddress, colIndex } from './addr.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const word = m[0]
  const addr = parseAddress(word)
  if (!addr) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  const key = formatAddress(addr)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
  const content = s.slice(word.length).replace(/^[ \t]+/, '')
  cells.set(key, { addr, content })
}

const sorted = [...cells.values()].sort((a, b) => colIndex(a.addr) - colIndex(b.addr) || a.addr.row - b.addr.row)

function out(s) {
  process.stdout.write(s)
}

if (mode === 'values') {
  const sheet = new Sheet(cells)
  const res = []
  for (const c of sorted) res.push(`${formatAddress(c.addr)}=${sheet.print(sheet.get(formatAddress(c.addr)))}\n`)
  out(res.join(''))
} else {
  const res = []
  for (const c of sorted) {
    let line = formatAddress(c.addr) + ':'
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const set = new Map()
        collect(ast, set)
        const list = [...set.values()].sort((a, b) => colIndex(a) - colIndex(b) || a.row - b.row)
        for (const a of list) line += ' ' + formatAddress(a)
      }
    }
    res.push(line + '\n')
  }
  out(res.join(''))
}

function add(set, a) {
  if (a) set.set(formatAddress(a), a)
}
function collect(n, set) {
  switch (n.t) {
    case 'ref': add(set, parseAddress(n.name)); break
    case 'range': {
      const a = parseAddress(n.a)
      const b = parseAddress(n.b)
      if (!a || !b) break
      const c1 = Math.min(colIndex(a), colIndex(b)), c2 = Math.max(colIndex(a), colIndex(b))
      const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
      for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) add(set, { col: c, row: r })
      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': for (const x of n.args) collect(x, set); break
  }
}
"}

{"file_path":"src/addr.js","content":"// Address: { col: 1..702, row: 1..999 }
export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + (L.charCodeAt(1) - 64)
  return { col, row }
}

export function colIndex(a) {
  return a.col
}

export function formatAddress(a) {
  const c = a.col
  const L = c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
  return L + a.row
}
"}

{"file_path":"src/parse.js","content":"// Returns an AST, or null when the grammar rejects the body.
class Reject extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else throw new Reject()
  }
  return toks
}

export function parseFormula(body) {
  try {
    const toks = tokenize(body)
    let p = 0
    const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
    const expect = (v) => { if (!isOp(v)) throw new Reject(); p++ }

    const CMP = ['=', '<>', '<', '<=', '>', '>=']
    function cmp() {
      let l = add()
      while (p < toks.length && toks[p].k === 'op' && CMP.includes(toks[p].v)) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: add() }
      }
      return l
    }
    function add() {
      let l = mul()
      while (isOp('+') || isOp('-')) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: mul() }
      }
      return l
    }
    function mul() {
      let l = pow()
      while (isOp('*') || isOp('/')) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: pow() }
      }
      return l
    }
    function pow() {
      const l = unary()
      if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
      return l
    }
    function unary() {
      if (isOp('-') || isOp('+')) {
        const op = toks[p++].v
        return { t: 'un', op, e: unary() }
      }
      return primary()
    }
    function primary() {
      if (p >= toks.length) throw new Reject()
      const tk = toks[p]
      if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
      if (tk.k === 'op') {
        if (tk.v === '(') { p++; const e = cmp(); expect(')'); return e }
        throw new Reject()
      }
      p++
      if (isOp('(')) {
        p++
        const args = []
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          expect(')')
          break
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', name: tk.v }
    }
    function arg() {
      if (
        p + 2 < toks.length && toks[p].k === 'word' && toks[p + 1].k === 'op' && toks[p + 1].v === ':' && toks[p + 2].k === 'word'
      ) {
        const after = toks[p + 3]
        if (after && after.k === 'op' && (after.v === ',' || after.v === ')')) {
          const r = { t: 'range', a: toks[p].v, b: toks[p + 2].v }
          p += 3
          return r
        }
        throw new Reject()
      }
      return cmp()
    }
    const ast = cmp()
    if (p !== toks.length) throw new Reject()
    return ast
  } catch (e) {
    if (e instanceof Reject) return null
    throw e
  }
}
"}

